import React, { useState } from 'react';
import restaurantService from '../../../services/restaurantService';
import { useAuth } from '../../hooks/useAuth';
import { useNavigate } from 'react-router-dom';

const AddRestaurant = () => {
  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [contactNumber, setContactNumber] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { token } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError('');
    try {
      const newRestaurant = { name, address, contactNumber };
      const savedRestaurant = await restaurantService.createRestaurant(newRestaurant, token);
      console.log('Restaurant created:', savedRestaurant);
      setLoading(false);
      navigate('/restaurant/dashboard'); // Redirect to restaurant dashboard
    } catch (err) {
      setError(err.message || 'Failed to create restaurant');
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Add New Restaurant</h2>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="name">Name:</label>
          <input type="text" id="name" value={name} onChange={(e) => setName(e.target.value)} required />
        </div>
        <div>
          <label htmlFor="address">Address:</label>
          <input type="text" id="address" value={address} onChange={(e) => setAddress(e.target.value)} required />
        </div>
        <div>
          <label htmlFor="contactNumber">Contact Number:</label>
          <input type="text" id="contactNumber" value={contactNumber} onChange={(e) => setContactNumber(e.target.value)} />
        </div>
        <button type="submit" disabled={loading}>
          {loading ? 'Creating...' : 'Create Restaurant'}
        </button>
      </form>
    </div>
  );
};

export default AddRestaurant;
